/**
 * Biome hazard zones that turn the arena into a weapon (pure logic, no rendering).
 *   magma   lava pools: enemies knocked into lava die on the spot
 *   peaks   ice patches: knocked enemies keep sliding and splat on walls
 *   dunes   quicksand: everything slows; small enemies that linger sink
 *   meadow  thorn bushes: enemies get scratched, knocked ones get skewered
 * The pools themselves are generated by createFieldArena (src/world/fieldArena.ts);
 * the per-step rules run in src/game/systems/arena.ts on the host.
 */

export type HazardKind = 'lava' | 'ice' | 'quicksand' | 'thorns';

export interface HazardZone {
  x: number;
  z: number;
  r: number;
  kind: HazardKind;
}

export const hazardTuning = {
  /** Knockback speed (m/s) that counts as "knocked into" a hazard. */
  knockSpeed: 4,
  /** Ice: knockback decays this much slower (enemies slide). */
  iceSlide: 6,
  /** Ice: an enemy sliding this fast into a wall splats. */
  splatSpeed: 5,
  /** Share of max life a wall splat takes from normal enemies. */
  splatFrac: 0.6,
  /** Quicksand: movement multiplier for heroes, slow amount for enemies. */
  sandHero: 0.55,
  sandSlow: 0.55,
  /** Quicksand: seconds before a small enemy (xp <= sinkXp) sinks. */
  sinkTime: 2.5,
  sinkXp: 2,
  /** Thorns: share of max life per tick (every 0.5 s) for enemies inside, and slow. */
  thornTick: 0.06,
  thornSlow: 0.3,
  thornHero: 0.85,
  /** Thorns: share of max life when knocked in. */
  thornKnock: 0.45,
  /** Elites and the Reaper only lose this share of max life to an instant-kill hazard. */
  eliteFrac: 0.25,
  /** Score bonus per environmental kill: (base + perStage x stage) x combo multiplier. */
  envScore: 40,
  envScorePerStage: 20,
};

/** Index of the first hazard of `kind` containing (x, z), or -1. */
export function hazardAt(zones: readonly HazardZone[], x: number, z: number, kind?: HazardKind): number {
  for (let i = 0; i < zones.length; i++) {
    const h = zones[i];
    if (kind && h.kind !== kind) continue;
    if ((x - h.x) ** 2 + (z - h.z) ** 2 < h.r * h.r) return i;
  }
  return -1;
}

/** Was this enemy thrown in (fast knockback) rather than walking in? */
export function knockedIn(kx: number, kz: number): boolean {
  return kx * kx + kz * kz > hazardTuning.knockSpeed * hazardTuning.knockSpeed;
}

/** Hero movement multiplier on the ground at (x, z) (quicksand and thorns slow you). */
export function heroGroundMul(zones: readonly HazardZone[], x: number, z: number): number {
  const i = hazardAt(zones, x, z);
  if (i < 0) return 1;
  const k = zones[i].kind;
  return k === 'quicksand' ? hazardTuning.sandHero : k === 'thorns' ? hazardTuning.thornHero : 1;
}

/** Score for one environmental kill. */
export function envKillScore(stage: number, multiplier: number): number {
  return (hazardTuning.envScore + hazardTuning.envScorePerStage * stage) * multiplier;
}

/** Biome id -> the hazard it adds on top of its pools (lava and ice come from the biome's pools). */
export function biomeHazard(biomeId: string): HazardKind | null {
  if (biomeId === 'dunes') return 'quicksand';
  if (biomeId === 'meadow') return 'thorns';
  return null;
}
